420	void DistributedSink::writeSync(const Block & block)
421	{
422	    OpenTelemetrySpanHolder span(__PRETTY_FUNCTION__);
423	
424	    const Settings & settings = context->getSettingsRef();
425	    const auto & shards_info = cluster->getShardsInfo();
426	    Block block_to_send = removeSuperfluousColumns(block);
427	
428	    size_t start = 0;
429	    size_t end = shards_info.size();
430	
431	    if (settings.insert_shard_id)
432	    {
433	        start = settings.insert_shard_id - 1;
434	        end = settings.insert_shard_id;
435	    }
436	
437	    if (!pool)
438	    {
439	        /// Deferred initialization. Only for sync insertion.
440	        initWritingJobs(block_to_send, start, end);
441	
442	        size_t jobs_count = random_shard_insert ? 1 : (remote_jobs_count + local_jobs_count);
443	        size_t max_threads = std::min<size_t>(settings.max_distributed_connections, jobs_count);
444	        pool.emplace(/* max_threads_= */ max_threads,
445	                     /* max_free_threads_= */ max_threads,
446	                     /* queue_size_= */ jobs_count);
447	
448	        if (!throttler && (settings.max_network_bandwidth || settings.max_network_bytes))
449	        {
450	            throttler = std::make_shared<Throttler>(settings.max_network_bandwidth, settings.max_network_bytes,
451	                                                    "Network bandwidth limit for a query exceeded.");
452	        }
453	
454	        watch.restart();
455	    }
456	
457	    watch_current_block.restart();
458	
459	    if (random_shard_insert)
460	    {
461	        start = storage.getRandomShardIndex(shards_info);
462	        end = start + 1;
463	    }
464	
465	    size_t num_shards = end - start;
466	
467	    span.addAttribute("clickhouse.start_shard", start);
468	    span.addAttribute("clickhouse.end_shard", end);
469	    span.addAttribute("db.statement", this->query_string);
470	
471	    if (num_shards > 1)
472	    {
473	        auto current_selector = createSelector(block);
474	
475	        /// Prepare row numbers for needed shards
476	        for (size_t shard_index : collections::range(start, end))
477	            per_shard_jobs[shard_index].shard_current_block_permutation.resize(0);
478	
479	        for (size_t i = 0; i < block.rows(); ++i)
480	            per_shard_jobs[current_selector[i]].shard_current_block_permutation.push_back(i);
481	    }
482	
483	    try
484	    {
485	        /// Run jobs in parallel for each block and wait them
486	        finished_jobs_count = 0;
487	        for (size_t shard_index : collections::range(start, end))
488	            for (JobReplica & job : per_shard_jobs[shard_index].replicas_jobs)
489	                pool->scheduleOrThrowOnError(runWritingJob(job, block_to_send, num_shards));
490	    }
491	    catch (...)
492	    {
493	        pool->wait();
494	        throw;
495	    }
496	
497	    try
498	    {
499	        waitForJobs();
500	    }
501	    catch (Exception & exception)
502	    {
503	        exception.addMessage(getCurrentStateDescription());
504	        span.addAttribute(exception);
505	        throw;
506	    }
507	
508	    inserted_blocks += 1;
509	    inserted_rows += block.rows();
510	}
