611	void DistributedSink::writeAsyncImpl(const Block & block, size_t shard_id)
612	{
613	    OpenTelemetrySpanHolder span("DistributedSink::writeAsyncImpl()");
614	
615	    const auto & shard_info = cluster->getShardsInfo()[shard_id];
616	    const auto & settings = context->getSettingsRef();
617	    Block block_to_send = removeSuperfluousColumns(block);
618	
619	    span.addAttribute("clickhouse.shard_num", shard_info.shard_num);
620	    span.addAttribute("clickhouse.written_rows", block.rows());
621	
622	    if (shard_info.hasInternalReplication())
623	    {
624	        if (shard_info.isLocal() && settings.prefer_localhost_replica)
625	            /// Prefer insert into current instance directly
626	            writeToLocal(block_to_send, shard_info.getLocalNodeCount());
627	        else
628	        {
629	            const auto & path = shard_info.insertPathForInternalReplication(
630	                settings.prefer_localhost_replica,
631	                settings.use_compact_format_in_distributed_parts_names);
632	            if (path.empty())
633	                throw Exception("Directory name for async inserts is empty", ErrorCodes::LOGICAL_ERROR);
634	            writeToShard(block_to_send, {path});
635	        }
636	    }
637	    else
638	    {
639	        if (shard_info.isLocal() && settings.prefer_localhost_replica)
640	            writeToLocal(block_to_send, shard_info.getLocalNodeCount());
641	
642	        std::vector<std::string> dir_names;
643	        for (const auto & address : cluster->getShardsAddresses()[shard_id])
644	            if (!address.is_local || !settings.prefer_localhost_replica)
645	                dir_names.push_back(address.toFullString(settings.use_compact_format_in_distributed_parts_names));
646	
647	        if (!dir_names.empty())
648	            writeToShard(block_to_send, dir_names);
649	    }
650	}
