669	void DistributedSink::writeToShard(const Block & block, const std::vector<std::string> & dir_names)
670	{
671	    OpenTelemetrySpanHolder span(__PRETTY_FUNCTION__);
672	
673	    const auto & settings = context->getSettingsRef();
674	    const auto & distributed_settings = storage.getDistributedSettingsRef();
675	
676	    bool fsync = distributed_settings.fsync_after_insert;
677	    bool dir_fsync = distributed_settings.fsync_directories;
678	
679	    std::string compression_method = Poco::toUpper(settings.network_compression_method.toString());
680	    std::optional<int> compression_level;
681	
682	    if (compression_method == "ZSTD")
683	        compression_level = settings.network_zstd_compression_level;
684	
685	    CompressionCodecFactory::instance().validateCodec(compression_method, compression_level, !settings.allow_suspicious_codecs, settings.allow_experimental_codecs);
686	    CompressionCodecPtr compression_codec = CompressionCodecFactory::instance().get(compression_method, compression_level);
687	
688	    /// tmp directory is used to ensure atomicity of transactions
689	    /// and keep monitor thread out from reading incomplete data
690	    std::string first_file_tmp_path;
691	
692	    auto reservation = storage.getStoragePolicy()->reserveAndCheck(block.bytes());
693	    const auto disk = reservation->getDisk();
694	    auto disk_path = disk->getPath();
695	    auto data_path = storage.getRelativeDataPath();
696	
697	    auto make_directory_sync_guard = [&](const std::string & current_path)
698	    {
699	        SyncGuardPtr guard;
700	        if (dir_fsync)
701	        {
702	            const std::string relative_path(data_path + current_path);
703	            guard = disk->getDirectorySyncGuard(relative_path);
704	        }
705	        return guard;
706	    };
707	
708	    auto it = dir_names.begin();
709	    /// on first iteration write block to a temporary directory for subsequent
710	    /// hardlinking to ensure the inode is not freed until we're done
711	    {
712	        const std::string path(disk_path + data_path + *it);
713	        const std::string tmp_path(path + "/tmp/");
714	
715	        fs::create_directory(path);
716	        fs::create_directory(tmp_path);
717	
718	        const std::string file_name(toString(storage.file_names_increment.get()) + ".bin");
719	
720	        first_file_tmp_path = tmp_path + file_name;
721	
722	        /// Write batch to temporary location
723	        {
724	            auto tmp_dir_sync_guard = make_directory_sync_guard(*it + "/tmp/");
725	
726	            WriteBufferFromFile out{first_file_tmp_path};
727	            CompressedWriteBuffer compress{out, compression_codec};
728	            NativeWriter stream{compress, DBMS_TCP_PROTOCOL_VERSION, block.cloneEmpty()};
729	
730	            /// Prepare the header.
731	            /// See also readDistributedHeader() in DirectoryMonitor (for reading side)
732	            ///
733	            /// We wrap the header into a string for compatibility with older versions:
734	            /// a shard will able to read the header partly and ignore other parts based on its version.
735	            WriteBufferFromOwnString header_buf;
736	            writeVarUInt(DBMS_TCP_PROTOCOL_VERSION, header_buf);
737	            writeStringBinary(query_string, header_buf);
738	            context->getSettingsRef().write(header_buf);
739	
740	            if (context->getClientInfo().client_trace_context.trace_id != UUID() && CurrentThread::isInitialized())
741	            {
742	                // if the distributed tracing is enabled, use the trace context in current thread as parent of next span
743	                auto client_info = context->getClientInfo();
744	                client_info.client_trace_context = CurrentThread::get().thread_trace_context;
745	                client_info.write(header_buf, DBMS_TCP_PROTOCOL_VERSION);
746	            }
747	            else
748	            {
749	                context->getClientInfo().write(header_buf, DBMS_TCP_PROTOCOL_VERSION);
750	            }
751	
752	            writeVarUInt(block.rows(), header_buf);
753	            writeVarUInt(block.bytes(), header_buf);
754	            writeStringBinary(block.cloneEmpty().dumpStructure(), header_buf); /// obsolete
755	            /// Write block header separately in the batch header.
756	            /// It is required for checking does conversion is required or not.
757	            {
758	                NativeWriter header_stream{header_buf, DBMS_TCP_PROTOCOL_VERSION, block.cloneEmpty()};
759	                header_stream.write(block.cloneEmpty());
760	            }
761	
762	            /// Add new fields here, for example:
763	            /// writeVarUInt(my_new_data, header_buf);
764	            /// And note that it is safe, because we have checksum and size for header.
765	
766	            /// Write the header.
767	            const StringRef header = header_buf.stringRef();
768	            writeVarUInt(DBMS_DISTRIBUTED_SIGNATURE_HEADER, out);
769	            writeStringBinary(header, out);
770	            writePODBinary(CityHash_v1_0_2::CityHash128(header.data, header.size), out);
771	
772	            stream.write(block);
773	
774	            compress.finalize();
775	            out.finalize();
776	            if (fsync)
777	                out.sync();
778	        }
779

779	
780	        // Create hardlink here to reuse increment number
781	        const std::string block_file_path(fs::path(path) / file_name);
782	        createHardLink(first_file_tmp_path, block_file_path);
783	        auto dir_sync_guard = make_directory_sync_guard(*it);
784	    }
785	    ++it;
786	
787	    /// Make hardlinks
788	    for (; it != dir_names.end(); ++it)
789	    {
790	        const std::string path(fs::path(disk_path) / (data_path + *it));
791	        fs::create_directory(path);
792	
793	        const std::string block_file_path(fs::path(path) / (toString(storage.file_names_increment.get()) + ".bin"));
794	        createHardLink(first_file_tmp_path, block_file_path);
795	        auto dir_sync_guard = make_directory_sync_guard(*it);
796	    }
797	
798	    auto file_size = fs::file_size(first_file_tmp_path);
799	    /// remove the temporary file, enabling the OS to reclaim inode after all threads
800	    /// have removed their corresponding files
801	    fs::remove(first_file_tmp_path);
802	
803	    /// Notify
804	    auto sleep_ms = context->getSettingsRef().distributed_directory_monitor_sleep_time_ms;
805	    for (const auto & dir_name : dir_names)
806	    {
807	        auto & directory_monitor = storage.requireDirectoryMonitor(disk, dir_name, /* startup= */ false);
808	        directory_monitor.addAndSchedule(file_size, sleep_ms.totalMilliseconds());
809	    }
810	}
