133	    struct DistributedHeader
134	    {
135	        UInt64 revision = 0;
136	        Settings insert_settings;
137	        std::string insert_query;
138	        ClientInfo client_info;
139	
140	        /// .bin file cannot have zero rows/bytes.
141	        size_t rows = 0;
142	        size_t bytes = 0;
143	
144	        /// dumpStructure() of the header -- obsolete
145	        std::string block_header_string;
146	        Block block_header;
147	    };
148	
149	    DistributedHeader readDistributedHeader(ReadBufferFromFile & in, Poco::Logger * log)
150	    {
151	        DistributedHeader distributed_header;
152	
153	        UInt64 query_size;
154	        readVarUInt(query_size, in);
155	
156	        if (query_size == DBMS_DISTRIBUTED_SIGNATURE_HEADER)
157	        {
158	            /// Read the header as a string.
159	            String header_data;
160	            readStringBinary(header_data, in);
161	
162	            /// Check the checksum of the header.
163	            CityHash_v1_0_2::uint128 checksum;
164	            readPODBinary(checksum, in);
165	            assertChecksum(checksum, CityHash_v1_0_2::CityHash128(header_data.data(), header_data.size()));
166	
167	            /// Read the parts of the header.
168	            ReadBufferFromString header_buf(header_data);
169	
170	            readVarUInt(distributed_header.revision, header_buf);
171	            if (DBMS_TCP_PROTOCOL_VERSION < distributed_header.revision)
172	            {
173	                LOG_WARNING(log, "ClickHouse shard version is older than ClickHouse initiator version. It may lack support for new features.");
174	            }
175	
176	            readStringBinary(distributed_header.insert_query, header_buf);
177	            distributed_header.insert_settings.read(header_buf);
178	
179	            if (header_buf.hasPendingData())
180	                distributed_header.client_info.read(header_buf, distributed_header.revision);
181	
182	            if (header_buf.hasPendingData())
183	            {
184	                readVarUInt(distributed_header.rows, header_buf);
185	                readVarUInt(distributed_header.bytes, header_buf);
186	                readStringBinary(distributed_header.block_header_string, header_buf);
187	            }
188	
189	            if (header_buf.hasPendingData())
190	            {
191	                NativeReader header_block_in(header_buf, distributed_header.revision);
192	                distributed_header.block_header = header_block_in.read();
193	                if (!distributed_header.block_header)
194	                    throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA,
195	                        "Cannot read header from the {} batch. Data was written with protocol version {}, current version: {}",
196	                            in.getFileName(), distributed_header.revision, DBMS_TCP_PROTOCOL_VERSION);
197	            }
198	
199	            /// Add handling new data here, for example:
200	            ///
201	            /// if (header_buf.hasPendingData())
202	            ///     readVarUInt(my_new_data, header_buf);
203	            ///
204	            /// And note that it is safe, because we have checksum and size for header.
205	
206	            return distributed_header;
207	        }
208	
209	        if (query_size == DBMS_DISTRIBUTED_SIGNATURE_HEADER_OLD_FORMAT)
210	        {
211	            distributed_header.insert_settings.read(in, SettingsWriteFormat::BINARY);
212	            readStringBinary(distributed_header.insert_query, in);
213	            return distributed_header;
214	        }
215	
216	        distributed_header.insert_query.resize(query_size);
217	        in.readStrict(distributed_header.insert_query.data(), query_size);
218	
219	        return distributed_header;
220	    }
