222	    /// 'remote_error' argument is used to decide whether some errors should be
223	    /// ignored or not, in particular:
224	    ///
225	    /// - ATTEMPT_TO_READ_AFTER_EOF should not be ignored
226	    ///   if we receive it from remote (receiver), since:
227	    ///   - the sender will got ATTEMPT_TO_READ_AFTER_EOF when the client just go away,
228	    ///     i.e. server had been restarted
229	    ///   - since #18853 the file will be checked on the sender locally, and
230	    ///     if there is something wrong with the file itself, we will receive
231	    ///     ATTEMPT_TO_READ_AFTER_EOF not from the remote at first
232	    ///     and mark batch as broken.
233	    bool isFileBrokenErrorCode(int code, bool remote_error)
234	    {
235	        return code == ErrorCodes::CHECKSUM_DOESNT_MATCH
236	            || code == ErrorCodes::EMPTY_DATA_PASSED
237	            || code == ErrorCodes::TOO_LARGE_SIZE_COMPRESSED
238	            || code == ErrorCodes::CANNOT_READ_ALL_DATA
239	            || code == ErrorCodes::UNKNOWN_CODEC
240	            || code == ErrorCodes::CANNOT_DECOMPRESS
241	            || code == ErrorCodes::DISTRIBUTED_BROKEN_BATCH_INFO
242	            || code == ErrorCodes::DISTRIBUTED_BROKEN_BATCH_FILES
243	            || (!remote_error && code == ErrorCodes::ATTEMPT_TO_READ_AFTER_EOF);
244	    }
245	
246	    /// Can the batch be split and send files from batch one-by-one instead?
247	    bool isSplittableErrorCode(int code, bool remote)
248	    {
249	        return code == ErrorCodes::MEMORY_LIMIT_EXCEEDED
250	            /// FunctionRange::max_elements and similar
251	            || code == ErrorCodes::ARGUMENT_OUT_OF_BOUND
252	            || code == ErrorCodes::TOO_MANY_PARTS
253	            || code == ErrorCodes::TOO_MANY_BYTES
254	            || code == ErrorCodes::TOO_MANY_ROWS_OR_BYTES
255	            || code == ErrorCodes::TOO_MANY_PARTITIONS
256	            || code == ErrorCodes::DISTRIBUTED_TOO_MANY_PENDING_BYTES
257	            || code == ErrorCodes::DISTRIBUTED_BROKEN_BATCH_INFO
258	            || isFileBrokenErrorCode(code, remote)
259	        ;
260	    }
