610	void StorageDistributedDirectoryMonitor::processFile(const std::string & file_path)
611	{
612	    Stopwatch watch;
613	    auto timeouts = ConnectionTimeouts::getTCPTimeoutsWithFailover(storage.getContext()->getSettingsRef());
614	
615	    try
616	    {
617	        CurrentMetrics::Increment metric_increment{CurrentMetrics::DistributedSend};
618	
619	        ReadBufferFromFile in(file_path);
620	        const auto & distributed_header = readDistributedHeader(in, log);
621	
622	        LOG_DEBUG(log, "Started processing `{}` ({} rows, {} bytes)", file_path,
623	            formatReadableQuantity(distributed_header.rows),
624	            formatReadableSizeWithBinarySuffix(distributed_header.bytes));
625	
626	        auto connection = pool->get(timeouts, &distributed_header.insert_settings);
627	        RemoteInserter remote{*connection, timeouts,
628	            distributed_header.insert_query,
629	            distributed_header.insert_settings,
630	            distributed_header.client_info};
631	        bool compression_expected = connection->getCompression() == Protocol::Compression::Enable;
632	        writeRemoteConvert(distributed_header, remote, compression_expected, in, log);
633	        remote.onFinish();
634	    }
635	    catch (Exception & e)
636	    {
637	        e.addMessage(fmt::format("While sending {}", file_path));
638	        maybeMarkAsBroken(file_path, e);
639	        throw;
640	    }
641	
642	    auto dir_sync_guard = getDirectorySyncGuard(dir_fsync, disk, relative_path);
643	    markAsSend(file_path);
644	    LOG_TRACE(log, "Finished processing `{}` (took {} ms)", file_path, watch.elapsedMilliseconds());
645	}
