72	OpenTelemetrySpanHolder::OpenTelemetrySpanHolder(const std::string & _operation_name)
73	{
74	    trace_id = 0;
75	
76	    if (!CurrentThread::isInitialized())
77	    {
78	        // There may be no thread context if we're running inside the
79	        // clickhouse-client, e.g. reading an external table provided with the
80	        // `--external` option.
81	        return;
82	    }
83	
84	    auto & thread = CurrentThread::get();
85	
86	    trace_id = thread.thread_trace_context.trace_id;
87	    if (trace_id == UUID())
88	        return;
89	
90	    parent_span_id = thread.thread_trace_context.span_id;
91	    span_id = thread_local_rng();
92	    operation_name = _operation_name;
93	    start_time_us = std::chrono::duration_cast<std::chrono::microseconds>(
94	        std::chrono::system_clock::now().time_since_epoch()).count();
95	
96	    thread.thread_trace_context.span_id = span_id;
97	}
