100	OpenTelemetrySpanHolder::~OpenTelemetrySpanHolder()
101	{
102	    try
103	    {
104	        if (trace_id == UUID())
105	            return;
106	
107	        // First of all, return old value of current span.
108	        auto & thread = CurrentThread::get();
109	        assert(thread.thread_trace_context.span_id == span_id);
110	        thread.thread_trace_context.span_id = parent_span_id;
111	
112	        // Not sure what's the best way to access the log from here.
113	        auto * thread_group = CurrentThread::getGroup().get();
114	        // Not sure whether and when this can be null.
115	        if (!thread_group)
116	            return;
117	
118	        ContextPtr context;
119	        {
120	            std::lock_guard lock(thread_group->mutex);
121	            context = thread_group->query_context.lock();
122	        }
123	
124	        if (!context)
125	        {
126	            // Both global and query contexts can be null when executing a
127	            // background task, and global context can be null for some
128	            // queries.
129	            return;
130	        }
131	
132	        auto log = context->getOpenTelemetrySpanLog();
133	        if (!log)
134	        {
135	            // The log might be disabled.
136	            return;
137	        }
138	
139	        finish_time_us = std::chrono::duration_cast<std::chrono::microseconds>(
140	            std::chrono::system_clock::now().time_since_epoch()).count();
141	
142	        log->add(OpenTelemetrySpanLogElement(
143	                     static_cast<OpenTelemetrySpan>(*this)));
144	    }
145	    catch (...)
146	    {
147	        tryLogCurrentException(__FUNCTION__);
148	    }
149	}
