183	bool OpenTelemetryTraceContext::parseTraceparentHeader(const std::string & traceparent,
184	    std::string & error)
185	{
186	    trace_id = 0;
187	
188	    // Version 00, which is the only one we can parse, is fixed width. Use this
189	    // fact for an additional sanity check.
190	    const int expected_length = strlen("xx-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx-xxxxxxxxxxxxxxxx-xx");
191	    if (traceparent.length() != expected_length)
192	    {
193	        error = fmt::format("unexpected length {}, expected {}",
194	            traceparent.length(), expected_length);
195	        return false;
196	    }
197	
198	    const char * data = traceparent.data();
199	
200	    uint8_t version = unhex2(data);
201	    data += 2;
202	
203	    if (version != 0)
204	    {
205	        error = fmt::format("unexpected version {}, expected 00", version);
206	        return false;
207	    }
208	
209	    if (*data != '-')
210	    {
211	        error = fmt::format("Malformed traceparant header: {}", traceparent);
212	        return false;
213	    }
214	
215	    ++data;
216	    UInt64 trace_id_higher_64 = unhexUInt<UInt64>(data);
217	    UInt64 trace_id_lower_64 = unhexUInt<UInt64>(data + 16);
218	    data += 32;
219	
220	    if (*data != '-')
221	    {
222	        error = fmt::format("Malformed traceparant header: {}", traceparent);
223	        return false;
224	    }
225	
226	    ++data;
227	    UInt64 span_id_64 = unhexUInt<UInt64>(data);
228	    data += 16;
229	
230	    if (*data != '-')
231	    {
232	        error = fmt::format("Malformed traceparant header: {}", traceparent);
233	        return false;
234	    }
235	
236	    ++data;
237	    this->trace_flags = unhex2(data);
238	
239	    // store the 128-bit trace id in big-endian order
240	    this->trace_id.toUnderType().items[0] = trace_id_higher_64;
241	    this->trace_id.toUnderType().items[1] = trace_id_lower_64;
242	    this->span_id = span_id_64;
243	    return true;
244	}
