246	
247	std::string OpenTelemetryTraceContext::composeTraceparentHeader() const
248	{
249	    // This span is a parent for its children, so we specify this span_id as a
250	    // parent id.
251	    return fmt::format("00-{:016x}{:016x}-{:016x}-{:02x}",
252	                       // Output the trace id in network byte order
253	                       trace_id.toUnderType().items[0],
254	                       trace_id.toUnderType().items[1],
255	                       span_id,
256	                       // This cast is needed because fmt is being weird and complaining that
257	                       // "mixing character types is not allowed".
258	                       static_cast<uint8_t>(trace_flags));
259	}
