713	    {
714	        if (file_indices.empty())
715	            return;
716	
717	        CurrentMetrics::Increment metric_increment{CurrentMetrics::DistributedSend};
718	
719	        Stopwatch watch;
720	
721	        LOG_DEBUG(parent.log, "Sending a batch of {} files ({} rows, {} bytes).", file_indices.size(),
722	            formatReadableQuantity(total_rows),
723	            formatReadableSizeWithBinarySuffix(total_bytes));
724	
725	        if (!recovered)
726	        {
727	            /// For deduplication in Replicated tables to work, in case of error
728	            /// we must try to re-send exactly the same batches.
729	            /// So we save contents of the current batch into the current_batch_file_path file
730	            /// and truncate it afterwards if all went well.
731	
732	            /// Temporary file is required for atomicity.
733	            String tmp_file{parent.current_batch_file_path + ".tmp"};
734	
735	            auto dir_sync_guard = getDirectorySyncGuard(dir_fsync, parent.disk, parent.relative_path);
736	            if (fs::exists(tmp_file))
737	                LOG_ERROR(parent.log, "Temporary file {} exists. Unclean shutdown?", backQuote(tmp_file));
738	
739	            {
740	                WriteBufferFromFile out{tmp_file, O_WRONLY | O_TRUNC | O_CREAT};
741	                writeText(out);
742	
743	                out.finalize();
744	                if (fsync)
745	                    out.sync();
746	            }
747	
748	            fs::rename(tmp_file, parent.current_batch_file_path);
749	        }
750	        auto timeouts = ConnectionTimeouts::getTCPTimeoutsWithFailover(parent.storage.getContext()->getSettingsRef());
751	        auto connection = parent.pool->get(timeouts);
752	
753	        bool batch_broken = false;
754	        bool batch_marked_as_broken = false;
755	        try
