776	                tryLogCurrentException(parent.log, "Failed to send batch due to");
777	                batch_broken = true;
778	                if (!e.isRemoteException() && e.code() == ErrorCodes::DISTRIBUTED_BROKEN_BATCH_FILES)
779	                    batch_marked_as_broken = true;
